import { resolve } from "node:path";
import { defineConfig } from "vite";

// Two pages, generated by scripts/build-pages.mjs from src/page.html:
// index.html (English, the default) and localized/es/index.html (Spanish).
// Firebase Hosting serves the Spanish one to es-* browsers (firebase.json › i18n).
export default defineConfig({
  server: { port: 5174 },
  build: {
    target: "es2022",
    sourcemap: false,
    rollupOptions: {
      input: {
        en: resolve(__dirname, "index.html"),
        es: resolve(__dirname, "localized/es/index.html"),
      },
    },
  },
});
